//! Identical minimal downstream model/read tools for all three handoff alternatives.
use super::sources::*;use crate::context::Context;use serde_json::{json,Value};
const RESULT:&str="{text:string,used_source_ids:[string],source_spans:[{source_id:string,revision:number,start_line:number,end_line:number}],facts:[{statement:string,quote:string,source_id:string,revision:number,start_line:number,end_line:number}],constraints_respected:[string],actions_performed:[string],uncertainties:[string]}";
pub fn execute(ctx:&mut Context,event:&Value,contract:&Value,sources:&Sources,cache:&mut super::read_cache::Cache)->Result<Value,String>{
 let utterance=event["utterance"].as_str().unwrap_or("");let mut supplied=capsule_evidence(&contract["capsule"]);
 let mut selection=ctx.call("dp05_receiver_select_or_complete",&json!({"role":"RECEIVER","instruction":format!("You are the minimal downstream draft receiver. Honor the authorized contract. Return JSON {{mode:'COMPLETE'|'READ',result:{}|null,reads:[{{source_id:string,start_line:number,end_line:number}}],reason:string}}. COMPLETE now is legal only if ACTUAL supplied passages or source-backed record evidence suffice. References, manifest titles, outlines and capsule summary without supporting text are NOT source facts. Each fact claim needs an EXACT copied quote from actual supplied evidence.text at the current cited span; displayed result text may paraphrase those claims. Provide the bounded requested draft and at least one sourced fact per required source; not a restatement of the user's request. Otherwise READ original bounded one-based inclusive ranges. Honor exclusions, current revisions, revoked sources and allowed actions. Preserve conditional scope: never turn a conditional preference or tie-break into an unconditional recommendation; use it only when its antecedent is established by the actual evidence. Do no actual external action or duplicate unknown action. All alternatives have the same receiver capabilities.",RESULT),"input":contract,"max_tokens":2500}))?;
 let direct_errors=result_errors(&selection["result"],utterance,sources,&supplied,&contract["mandatory"]["required_source_ids"]);
 let direct=selection["mode"].as_str()==Some("COMPLETE")&&direct_errors.is_empty();ctx.event("RECEIVER_BRANCH",&json!({"delegation_id":contract["mandatory"]["delegation_id"],"model_mode":selection["mode"],"branch":if direct{"COMPLETE_FROM_SUPPLIED_EVIDENCE"}else{"READ_ORIGINAL_SOURCES"},"errors":direct_errors}));
 let mut receipt=json!({"delegation_id":contract["mandatory"]["delegation_id"],"selected_reads":[],"served":[],"denied":[],"completion_from_supplied_capsule":direct});
 let mut result=if direct{selection["result"].clone()}else{
  if array(&selection["reads"]).is_empty(){ctx.event("RECEIVER_COMPLETION_REJECTED",&json!({"proposal":selection,"reason":"inadequate_actual_evidence_or_empty_read_plan"}));selection=ctx.call("dp05_receiver_recover_read_selection",&json!({"role":"RECEIVER","instruction":"The receiver has no accepted source-backed completion and selected no actual reads. Return JSON {reads:[{source_id:string,start_line:number,end_line:number}],reason:string}. Select current authorized original spans necessary for this actual bounded purpose. Manifest metadata is not facts. This is your single read-selection repair.","input":{"contract":contract,"previous_proposal":selection},"max_tokens":1000}))?;}
  ctx.event("RECEIVER_READ_SELECTION",&selection);ctx.event("SERVING_START",&json!({"goal_id":event["goal_id"],"shim_id":event["delegation_id"]}));let(p,d)=cache.serve(ctx,&selection["reads"],sources,&contract["mandatory"]["access_epoch"],&contract["mandatory"]["recipient"]);ctx.event("SERVING_END",&json!({"goal_id":event["goal_id"],"shim_id":event["delegation_id"]}));receipt["selected_reads"]=selection["reads"].clone();receipt["served"]=json!(p);receipt["denied"]=json!(d);supplied.extend(p);
  if supplied.is_empty(){ctx.event("RECEIVER_READ_RECEIPT",&receipt);return Ok(json!({"completed":false,"receipt":receipt,"reason":"NO_ACTUAL_RECEIVER_EVIDENCE"}));}
  ctx.call("dp05_receiver_result",&json!({"role":"RECEIVER","instruction":format!("Produce the requested small bounded draft from the authorized mandatory contract and ACTUAL supplied source evidence ONLY. Return JSON {}. Each fact claim needs an EXACT copied quote substring in supplied evidence.text with current original source span. Display text may paraphrase those claims. Include requested substantive content and supported caveats/unknowns. At least one sourced fact per required source. Do not echo request as a result or guess unseen content. Respect all exclusions and allowed/unknown actions. Preserve necessity and sufficiency of conditional rules: apply a tie-break only if its stated antecedent holds in actual evidence; otherwise keep it conditional or omit a recommendation. No real external action occurs.",RESULT),"input":{"contract":contract,"actual_evidence":supplied,"tool_denials":receipt["denied"]},"max_tokens":2500}))?
 };
 ctx.event("RECEIVER_READ_RECEIPT",&receipt);let mut errors=result_errors(&result,utterance,sources,&supplied,&contract["mandatory"]["required_source_ids"]);
 if !errors.is_empty(){ctx.event("RECEIVER_RESULT_REJECTED",&json!({"proposal":result,"errors":errors}));result=ctx.call("dp05_receiver_repair_result",&json!({"role":"RECEIVER","instruction":format!("Repair the rejected bounded draft from ONLY actual supplied evidence and mandatory conditions. Return JSON {}. Display text may paraphrase fact claims; each quote must be EXACTLY present in actual evidence.text at the current cited source span. Include substantive requested facts, not request echo. No forbidden or duplicate actions. Do not strengthen or weaken a condition or apply its preference when its antecedent does not hold. If impossible return text:null and uncertainties.",RESULT),"input":{"contract":contract,"actual_evidence":supplied,"rejected":result,"errors":errors},"max_tokens":2500}))?;errors=result_errors(&result,utterance,sources,&supplied,&contract["mandatory"]["required_source_ids"]);}
 ctx.event("AGENT_RESULT_AVAILABLE",&json!({"goal_id":event["goal_id"],"result":result,"host_contract_errors":errors}));Ok(json!({"completed":errors.is_empty(),"result":result,"receipt":receipt,"errors":errors}))
}
